+                type: ip
+                script:
+                  source: |
+                    Matcher m = /([^ ]+) .+/.matcher(doc["message"].value);
+                    if (m.matches()) {
+                      emit(m.group(1));
+                    }
+              # Test fetching from _source
+              ip_from_source:
+                type: ip
+                script:
+                  source: |
+                    Matcher m = /([^ ]+) .+/.matcher(params._source.message);
